SourceCode.Declaration:
/// <summary>
/// Data migration: FmVehicle → FmVehicle.
/// Run once as a runnable class (right-click the class, Set as startup object) or
/// from a batch job; uses doInsert/doUpdate (permitted exception).
/// </summary>
public class ConFmVehicleMigration
{
    private static int BatchSize = 1000;
}

Method.Source:
public void run()
{
    FmVehicle source;
    FmVehicle target;
    int migratedCount = 0;

    ttsbegin;
    while select source
    {
        // TODO: map fields from source to target
        target.clear();
        // target.Field = source.Field;
        if (target.RecId) target.doUpdate(); else target.doInsert();
        migratedCount++;
        if (migratedCount mod BatchSize == 0)
        {
            ttscommit;
            info(strFmt("Migrated %1 records", migratedCount));
            ttsbegin;
        }
    }
    ttscommit;
    info(strFmt("Migration complete. Total: %1", migratedCount));
}

public static void main(Args _args)
{
    ConFmVehicleMigration runObject = new ConFmVehicleMigration();
    runObject.run();
}
